describe('startDevServer', () => {
  let tmp: string;
  let instance: DevServerInstance | undefined;

  beforeEach(() => {
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-dev-'));
  });

  afterEach(async () => {
    if (instance) {
      await instance.close();
    }
    fs.rmSync(tmp, { recursive: true, force: true });
